import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { DEFAULT_BUDGET, BudgetExceededError } from '@dailies/core';
import { openDb, createRun, getRun, listEvents, addCost, unfinishedRuns, runPipeline } from '../src/index';
import type { Database, Stage } from '../src/index';

let db: Database;
let dataDir: string;

const input = {
  repoUrl: 'https://example.com/repo.git',
  since: '2026-01-01T00:00:00Z',
  until: '2026-01-02T00:00:00Z',
  budget: DEFAULT_BUDGET,
};
const noSleep = async () => {};

beforeEach(() => {
  db = openDb(':memory:');
  dataDir = mkdtempSync(join(tmpdir(), 'dailies-runner-'));
});

afterEach(() => {
  rmSync(dataDir, { recursive: true, force: true });
});

describe('runPipeline', () => {
  it('runs stages in order and stores readable artifacts', async () => {
    const order: string[] = [];
    const stages: Stage[] = [
      {
        name: 'ingest',
        maxAttempts: 1,
        run: async (ctx) => {
          order.push('ingest');
          ctx.log('ingest started');
          return { artifact: { sessions: 2 } };
        },
      },
      {
        name: 'edit',
        maxAttempts: 1,
        run: async (ctx) => {
          order.push('edit');
          const ingest = ctx.read<{ sessions: number }>('ingest');
          return { artifact: { beats: ingest.sessions } };
        },
      },
    ];
    const id = createRun(db, input);
    const status = await runPipeline(db, id, stages, { dataDir, sleep: noSleep });

    expect(status).toBe('needs_approval');
    expect(order).toEqual(['ingest', 'edit']);
    const ingestArtifact = JSON.parse(readFileSync(join(dataDir, 'runs', id, 'ingest.json'), 'utf8'));
    expect(ingestArtifact).toEqual({ sessions: 2 });
    const editArtifact = JSON.parse(readFileSync(join(dataDir, 'runs', id, 'edit.json'), 'utf8'));
    expect(editArtifact).toEqual({ beats: 2 });
    const events = listEvents(db, id);
    expect(events.map((e) => e.message)).toContain('ingest started');
    expect(events[0]!.stage).toBe('ingest');
  });

  it('retries a failing stage and succeeds on the second attempt', async () => {
    let attempts = 0;
    const stages: Stage[] = [
      {
        name: 'ingest',
        maxAttempts: 2,
        run: async () => {
          attempts += 1;
          if (attempts === 1) throw new Error('transient');
          return { artifact: { ok: true } };
        },
      },
    ];
    const sleeps: number[] = [];
    const id = createRun(db, input);
    const status = await runPipeline(db, id, stages, { dataDir, sleep: async (ms) => { sleeps.push(ms); } });

    expect(status).toBe('needs_approval');
    expect(attempts).toBe(2);
    expect(sleeps).toEqual([1000]); // 500 * 2^1
  });

  it('marks the run failed after maxAttempts', async () => {
    let attempts = 0;
    const stages: Stage[] = [
      {
        name: 'ingest',
        maxAttempts: 2,
        run: async () => {
          attempts += 1;
          throw new Error('boom');
        },
      },
    ];
    const sleeps: number[] = [];
    const id = createRun(db, input);
    const status = await runPipeline(db, id, stages, { dataDir, sleep: async (ms) => { sleeps.push(ms); } });

    expect(status).toBe('failed');
    expect(attempts).toBe(2);
    expect(sleeps).toEqual([1000]);
    const run = getRun(db, id);
    expect(run.status).toBe('failed');
    expect(run.reason).toBe('boom');
  });

  it('resumes after a crash without re-running completed stages', async () => {
    const calls = { a: 0, b: 0 };
    const a: Stage = { name: 'ingest', maxAttempts: 1, run: async () => { calls.a += 1; return { artifact: 1 }; } };
    let crash = true;
    const b: Stage = {
      name: 'edit',
      maxAttempts: 1,
      run: async () => {
        calls.b += 1;
        if (crash) throw new Error('boom');
        return { artifact: 2 };
      },
    };
    const id = createRun(db, input);
    const opts = { dataDir, sleep: noSleep };
    expect(await runPipeline(db, id, [a, b], opts)).toBe('failed');
    db.prepare("UPDATE runs SET status='running' WHERE id=?").run(id);
    db.prepare("UPDATE stages SET status='pending', attempt=0 WHERE run_id=? AND name='edit'").run(id);
    crash = false;
    expect(await runPipeline(db, id, [a, b], opts)).toBe('needs_approval');
    expect(calls).toEqual({ a: 1, b: 2 });
  });

  it('loops back at most twice, then blocks with the reason', async () => {
    let scriptCalls = 0;
    let groundCalls = 0;
    const stages: Stage[] = [
      { name: 'script', maxAttempts: 1, run: async () => { scriptCalls += 1; return { artifact: { ok: true } }; } },
      {
        name: 'ground',
        maxAttempts: 1,
        run: async () => {
          groundCalls += 1;
          return { artifact: { ok: false }, loopBackTo: 'script', reason: 'not enough evidence' };
        },
      },
    ];
    const id = createRun(db, input);
    const status = await runPipeline(db, id, stages, { dataDir, sleep: noSleep });

    expect(status).toBe('blocked');
    expect(scriptCalls).toBe(3);
    expect(groundCalls).toBe(3);
    const run = getRun(db, id);
    expect(run.loops).toBe(2);
    expect(run.reason).toBe('not enough evidence');
  });

  it('passes the loop-back reason to the stage as ctx.feedback', async () => {
    const scriptFeedback: (string | null)[] = [];
    let groundCalls = 0;
    const stages: Stage[] = [
      { name: 'script', maxAttempts: 1, run: async (ctx) => { scriptFeedback.push(ctx.feedback); return { artifact: {} }; } },
      {
        name: 'ground',
        maxAttempts: 1,
        run: async () => {
          groundCalls += 1;
          if (groundCalls === 1) return { artifact: {}, loopBackTo: 'script', reason: 'rewrite line 2' };
          return { artifact: { pass: true } };
        },
      },
    ];
    const id = createRun(db, input);
    const status = await runPipeline(db, id, stages, { dataDir, sleep: noSleep });

    expect(status).toBe('needs_approval');
    expect(scriptFeedback).toEqual([null, 'rewrite line 2']);
  });

  it('ends blocked with reason budget on BudgetExceededError', async () => {
    const stages: Stage[] = [
      { name: 'edit', maxAttempts: 5, run: async () => { throw new BudgetExceededError(0.7, 0.6); } },
    ];
    const id = createRun(db, input);
    const status = await runPipeline(db, id, stages, { dataDir, sleep: noSleep });

    expect(status).toBe('blocked');
    const run = getRun(db, id);
    expect(run.reason).toBe('budget');
  });

  it('honours a final status returned by a stage', async () => {
    let gateCalls = 0;
    const stages: Stage[] = [
      { name: 'ingest', maxAttempts: 1, run: async () => ({ artifact: {} }) },
      {
        name: 'gate',
        maxAttempts: 1,
        run: async () => {
          gateCalls += 1;
          return { artifact: { checks: [] }, final: { status: 'blocked', reason: 'secrets found' } };
        },
      },
    ];
    const id = createRun(db, input);
    const status = await runPipeline(db, id, stages, { dataDir, sleep: noSleep });

    expect(status).toBe('blocked');
    expect(gateCalls).toBe(1);
    const run = getRun(db, id);
    expect(run.reason).toBe('secrets found');
  });
});

describe('store', () => {
  it('addCost accumulates onto the run record', () => {
    const id = createRun(db, input);
    addCost(db, id, 0.12);
    addCost(db, id, 0.08);
    expect(getRun(db, id).costUsd).toBeCloseTo(0.2, 10);
  });

  it('unfinishedRuns lists only runs still running', async () => {
    const running = createRun(db, input);
    const finished = createRun(db, input);
    await runPipeline(db, finished, [{ name: 'ingest', maxAttempts: 1, run: async () => ({ artifact: {} }) }], {
      dataDir,
      sleep: noSleep,
    });

    const ids = unfinishedRuns(db);
    expect(ids).toContain(running);
    expect(ids).not.toContain(finished);
  });
});

import type SqliteDatabase from 'better-sqlite3';
import type { Budget } from '@dailies/core';

export type Database = SqliteDatabase.Database;

export type StageName = 'ingest' | 'edit' | 'verify' | 'script' | 'ground' | 'voice' | 'render' | 'review' | 'gate';
export type RunStatus = 'running' | 'needs_approval' | 'blocked' | 'failed';

export interface RunRecord {
  id: string;
  repoUrl: string;
  since: string;
  until: string;
  status: RunStatus;
  reason: string | null;
  costUsd: number;
  loops: number;
  budget: Budget;
  createdAt: string;
}

export interface StageContext {
  run: RunRecord;
  dataDir: string;
  runDir: string;
  read<T>(stage: StageName): T; // artifact of a completed stage; throws if absent
  log(message: string): void; // appends an event
  feedback: string | null; // reason passed by the last loop-back, if any
}

export interface StageResult<T> {
  artifact: T;
  loopBackTo?: StageName;
  reason?: string;
  final?: { status: 'needs_approval' | 'blocked'; reason: string };
}

export interface Stage<T = unknown> {
  name: StageName;
  maxAttempts: number;
  run(ctx: StageContext): Promise<StageResult<T>>;
}

import SqliteDatabase from 'better-sqlite3';
import type { Database } from './types';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, repo_url TEXT NOT NULL, since TEXT NOT NULL, until TEXT NOT NULL,
  status TEXT NOT NULL, reason TEXT, cost_usd REAL NOT NULL DEFAULT 0, loops INTEGER NOT NULL DEFAULT 0,
  budget TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stages (run_id TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 0,
  started_at TEXT, ended_at TEXT, error TEXT, PRIMARY KEY (run_id, name));
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, ts TEXT NOT NULL, stage TEXT, message TEXT NOT NULL);
`;

export function openDb(path: string): Database {
  const db = new SqliteDatabase(path);
  db.pragma('journal_mode = WAL');
  db.exec(SCHEMA);
  return db;
}

import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import type { Budget } from '@dailies/core';
import { newId } from '@dailies/core';
import type { Database, RunRecord, RunStatus } from './types';

interface RunRow {
  id: string;
  repo_url: string;
  since: string;
  until: string;
  status: RunStatus;
  reason: string | null;
  cost_usd: number;
  loops: number;
  budget: string;
  created_at: string;
}

function toRunRecord(row: RunRow): RunRecord {
  return {
    id: row.id,
    repoUrl: row.repo_url,
    since: row.since,
    until: row.until,
    status: row.status,
    reason: row.reason,
    costUsd: row.cost_usd,
    loops: row.loops,
    budget: JSON.parse(row.budget) as Budget,
    createdAt: row.created_at,
  };
}

export function createRun(db: Database, i: { repoUrl: string; since: string; until: string; budget: Budget }): string {
  const id = newId('run');
  const createdAt = new Date().toISOString();
  db.prepare(
    `INSERT INTO runs (id, repo_url, since, until, status, reason, cost_usd, loops, budget, created_at)
     VALUES (?, ?, ?, ?, 'running', NULL, 0, 0, ?, ?)`,
  ).run(id, i.repoUrl, i.since, i.until, JSON.stringify(i.budget), createdAt);
  return id;
}

export function getRun(db: Database, id: string): RunRecord {
  const row = db.prepare('SELECT * FROM runs WHERE id = ?').get(id) as RunRow | undefined;
  if (!row) throw new Error(`run not found: ${id}`);
  return toRunRecord(row);
}

export function listEvents(
  db: Database,
  runId: string,
  afterId = 0,
): { id: number; ts: string; stage: string | null; message: string }[] {
  return db
    .prepare('SELECT id, ts, stage, message FROM events WHERE run_id = ? AND id > ? ORDER BY id ASC')
    .all(runId, afterId) as { id: number; ts: string; stage: string | null; message: string }[];
}

export function addCost(db: Database, runId: string, usd: number): void {
  db.prepare('UPDATE runs SET cost_usd = cost_usd + ? WHERE id = ?').run(usd, runId);
}

export function unfinishedRuns(db: Database): string[] {
  return (db.prepare("SELECT id FROM runs WHERE status = 'running'").all() as { id: string }[]).map((r) => r.id);
}

export function appendEvent(db: Database, runId: string, stage: string | null, message: string): void {
  db.prepare('INSERT INTO events (run_id, ts, stage, message) VALUES (?, ?, ?, ?)').run(
    runId,
    new Date().toISOString(),
    stage,
    message,
  );
}

export function setRunFinal(db: Database, runId: string, status: RunStatus, reason: string | null): void {
  db.prepare('UPDATE runs SET status = ?, reason = ? WHERE id = ?').run(status, reason, runId);
}

export function incrementLoops(db: Database, runId: string): void {
  db.prepare('UPDATE runs SET loops = loops + 1 WHERE id = ?').run(runId);
}

interface StageRow {
  status: string;
  attempt: number;
}

export function getStageRow(db: Database, runId: string, name: string): StageRow | undefined {
  return db.prepare('SELECT status, attempt FROM stages WHERE run_id = ? AND name = ?').get(runId, name) as
    | StageRow
    | undefined;
}

export function isStageDone(db: Database, runId: string, name: string): boolean {
  return getStageRow(db, runId, name)?.status === 'done';
}

export function beginStageAttempt(db: Database, runId: string, name: string): number {
  const attempt = (getStageRow(db, runId, name)?.attempt ?? 0) + 1;
  const now = new Date().toISOString();
  db.prepare(
    `INSERT INTO stages (run_id, name, status, attempt, started_at, ended_at, error)
     VALUES (?, ?, 'running', ?, ?, NULL, NULL)
     ON CONFLICT(run_id, name) DO UPDATE SET status = 'running', attempt = excluded.attempt, started_at = excluded.started_at, ended_at = NULL, error = NULL`,
  ).run(runId, name, attempt, now);
  return attempt;
}

export function markStageDone(db: Database, runId: string, name: string): void {
  db.prepare("UPDATE stages SET status = 'done', ended_at = ? WHERE run_id = ? AND name = ?").run(
    new Date().toISOString(),
    runId,
    name,
  );
}

export function markStageFailed(db: Database, runId: string, name: string, error: string): void {
  db.prepare("UPDATE stages SET status = 'failed', ended_at = ?, error = ? WHERE run_id = ? AND name = ?").run(
    new Date().toISOString(),
    error,
    runId,
    name,
  );
}

export function resetStage(db: Database, runId: string, name: string): void {
  db.prepare(
    `INSERT INTO stages (run_id, name, status, attempt, started_at, ended_at, error)
     VALUES (?, ?, 'pending', 0, NULL, NULL, NULL)
     ON CONFLICT(run_id, name) DO UPDATE SET status = 'pending', attempt = 0, started_at = NULL, ended_at = NULL, error = NULL`,
  ).run(runId, name);
}

function artifactPath(dataDir: string, runId: string, stage: string): string {
  return join(dataDir, 'runs', runId, `${stage}.json`);
}

export function writeArtifact(dataDir: string, runId: string, stage: string, artifact: unknown): void {
  const path = artifactPath(dataDir, runId, stage);
  mkdirSync(dirname(path), { recursive: true });
  const tmp = `${path}.tmp-${process.pid}-${Date.now()}`;
  writeFileSync(tmp, JSON.stringify(artifact));
  renameSync(tmp, path);
}

export function readArtifact<T>(dataDir: string, runId: string, stage: string): T {
  const path = artifactPath(dataDir, runId, stage);
  if (!existsSync(path)) throw new Error(`artifact not found for stage ${stage}`);
  return JSON.parse(readFileSync(path, 'utf8')) as T;
}

import { join } from 'node:path';
import { BudgetExceededError } from '@dailies/core';
import {
  appendEvent,
  beginStageAttempt,
  getRun,
  incrementLoops,
  isStageDone,
  markStageDone,
  markStageFailed,
  readArtifact,
  resetStage,
  setRunFinal,
  writeArtifact,
} from './store';
import type { Database, RunStatus, Stage, StageContext, StageName } from './types';

const defaultSleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

export async function runPipeline(
  db: Database,
  runId: string,
  stages: Stage[],
  o: { dataDir: string; sleep?: (ms: number) => Promise<void> },
): Promise<RunStatus> {
  const sleep = o.sleep ?? defaultSleep;
  const runDir = join(o.dataDir, 'runs', runId);
  let feedback: string | null = null;

  let i = stages.findIndex((s) => !isStageDone(db, runId, s.name));
  if (i === -1) i = stages.length;

  while (i < stages.length) {
    const stage = stages[i]!;
    const ctx: StageContext = {
      run: getRun(db, runId),
      dataDir: o.dataDir,
      runDir,
      read: <T>(name: StageName) => readArtifact<T>(o.dataDir, runId, name),
      log: (message: string) => appendEvent(db, runId, stage.name, message),
      feedback,
    };

    const attempt = beginStageAttempt(db, runId, stage.name);
    try {
      const result = await stage.run(ctx);
      writeArtifact(o.dataDir, runId, stage.name, result.artifact);
      markStageDone(db, runId, stage.name);

      if (result.final) {
        setRunFinal(db, runId, result.final.status, result.final.reason);
        return result.final.status;
      }

      if (result.loopBackTo) {
        if (getRun(db, runId).loops < 2) {
          incrementLoops(db, runId);
          feedback = result.reason ?? null;
          const target = stages.findIndex((s) => s.name === result.loopBackTo);
          if (target === -1) throw new Error(`loopBackTo names an unknown stage: ${result.loopBackTo}`);
          for (let j = target; j < stages.length; j++) resetStage(db, runId, stages[j]!.name);
          i = target;
          continue;
        }
        setRunFinal(db, runId, 'blocked', result.reason ?? null);
        return 'blocked';
      }

      i += 1;
    } catch (err) {
      if (err instanceof BudgetExceededError) {
        setRunFinal(db, runId, 'blocked', 'budget');
        return 'blocked';
      }
      const message = err instanceof Error ? err.message : String(err);
      markStageFailed(db, runId, stage.name, message);
      if (attempt >= stage.maxAttempts) {
        setRunFinal(db, runId, 'failed', message);
        return 'failed';
      }
      await sleep(500 * 2 ** attempt);
    }
  }

  setRunFinal(db, runId, 'needs_approval', null);
  return 'needs_approval';
}

